import type { Argv, ArgumentsCamelCase } from 'yargs'
import { logger } from '../../logger'
import * as fs from 'fs'
// biome-ignore lint/style/noRestrictedImports: explain is CLI-only (Node.js); native path avoids pulling in sdk-build-core's TypeScript toolchain, saving ~350ms of startup time
import * as path from 'node:path'
import chalk from 'chalk'
// Subpath import — `@servicenow/sdk-api/docs` is a lean isomorphic module
// Importing from `@servicenow/sdk-api` directly would pull the full module graph
import { type DocFile, type DocsFs, filterDocs, findDocs, parseFrontmatter, scanDocs } from '@servicenow/sdk-api/docs'
import { withTelemetryEvent } from '../../telemetry'

// Node fs adapter for the primitives.
const nodeFsAdapter: DocsFs = {
    readdirSync: (p) => fs.readdirSync(p),
    statSync: (p) => fs.statSync(p),
    readFileSync: (p) => fs.readFileSync(p, 'utf-8'),
}

// ── Types ───────────────────────────────────────────────────────────────────

type Format = 'pretty' | 'raw'

interface Arguments {
    topic: string | undefined
    list: boolean | undefined
    format: Format
    peek: boolean | undefined
}

// ── Command ─────────────────────────────────────────────────────────────────

export function builder(yargs: Argv) {
    return yargs
        .positional('topic', {
            describe: 'Topic name or keyword to search for',
            type: 'string',
        })
        .option('list', {
            alias: 'l',
            describe: 'List topics. Combine with a topic to filter (e.g., --list flow)',
            type: 'boolean',
        })
        .option('format', {
            describe: 'Output format: "pretty" for terminal, "raw" for plain markdown',
            choices: ['pretty', 'raw'] as const,
            default: 'pretty' as Format,
        })
        .option('peek', {
            alias: 'p',
            describe: 'Show a brief summary instead of the full document',
            type: 'boolean',
        })
}

export async function handler(args: ArgumentsCamelCase<Arguments>): Promise<void> {
    const argFlags = {
        topic: args.topic,
        list: !!args.list,
        peek: !!args.peek,
        format: args.format,
    }

    try {
        await withTelemetryEvent({ event: 'explain', sdkDir: __dirname, errorData: argFlags }, () =>
            runExplain(args, argFlags)
        )
    } catch (error) {
        logger.error(error)
        process.exitCode = 1
    }
}

type ExplainOutcome = 'list' | 'single-match' | 'multi-match' | 'suggestions' | 'error'

async function runExplain(
    args: ArgumentsCamelCase<Arguments>,
    argFlags: { topic: string | undefined; list: boolean; peek: boolean; format: Format }
): Promise<{
    topic: string | undefined
    list: boolean
    peek: boolean
    format: Format
    outcome: ExplainOutcome
    matchCount: number
} | null> {
    const result = (outcome: ExplainOutcome, matchCount: number) => ({ ...argFlags, outcome, matchCount })

    const docsDir = resolveDocsDir()
    if (!docsDir) {
        logger.error('Could not find SDK documentation directory.')
        process.exitCode = 1
        return result('error', 0)
    }

    const docs = scanDocs(docsDir, nodeFsAdapter)
    const raw = args.format === 'raw'

    // List mode: show all topics, optionally filtered with strong/weak grouping
    if (args.list || !args.topic) {
        let matchCount: number
        if (args.topic) {
            const strong = findDocs(docs, args.topic)
            const allMatches = filterDocs(docs, args.topic)
            const weak = allMatches.filter((d) => !strong.includes(d))
            matchCount = strong.length + weak.length
            printTopicList(strong, weak, raw, true, !!args.peek)
        } else {
            matchCount = docs.length
            printTopicList(docs, [], raw, false, !!args.peek)
        }
        printDisambiguationHint(raw)
        return result('list', matchCount)
    }

    const matches = findDocs(docs, args.topic)

    // No precise match — try substring suggestions
    if (matches.length === 0) {
        const suggestions = filterDocs(docs, args.topic)
        if (suggestions.length > 0) {
            printMessage(`No matching topics for "${args.topic}", but these may be related:`, raw)
            printSummaries(suggestions, raw)
            printDisambiguationHint(raw)
            return result('suggestions', suggestions.length)
        }
        logger.error(`No matching topics for "${args.topic}"`)
        logger.info('Run `now-sdk explain --list` to see all available topics.')
        process.exitCode = 1
        // High-cardinality, low-signal — searched topic name varies wildly on miss.
        // Skip telemetry rather than pollute analytics.
        return null
    }

    // Multiple matches or peek mode — show summaries
    if (matches.length > 1 || args.peek) {
        if (matches.length > 1) {
            printMessage(`Multiple matching topics for "${args.topic}":`, raw)
        }
        printSummaries(matches, raw)
        if (matches.length > 1) {
            printDisambiguationHint(raw)
        }
        return result(matches.length > 1 ? 'multi-match' : 'single-match', matches.length)
    }

    // Single match — show full doc
    const match = matches[0]!
    const body = readDocBody(match)
    if (raw) {
        console.log(body)
    } else {
        printFormattedMarkdown(match.name, body, match.tags)
    }
    return result('single-match', matches.length)
}

// ── Document Loading & Parsing ──────────────────────────────────────────────

// Not unit-tested: depends on process.argv[1] which is set by the Node.js
// runtime. Validated manually via `now-sdk explain` invocations.
export function resolveDocsDir(): string | undefined {
    // The CLI binary lives at @servicenow/sdk/bin/index.js, so the SDK
    // package root is one level up from the binary's directory.
    // When globally installed, process.argv[1] may be a symlink in a bin
    // directory (e.g. /usr/local/bin/now-sdk) — resolve it to the real path
    // first so that the relative traversal reaches the actual package root.
    const binPath = process.argv[1]
    if (binPath) {
        let resolvedBinPath = binPath
        try {
            resolvedBinPath = fs.realpathSync(binPath)
        } catch {
            // realpathSync can fail if the path doesn't exist; fall back to the original
        }
        const sdkRoot = path.resolve(path.dirname(resolvedBinPath), '..')
        const docsDir = path.join(sdkRoot, 'docs')
        if (fs.existsSync(docsDir)) {
            return docsDir
        }
    }
    return undefined
}

/** Reads a doc file and returns the body with frontmatter stripped. */
function readDocBody(doc: DocFile): string {
    const content = fs.readFileSync(doc.filePath, 'utf-8')
    const { body } = parseFrontmatter(content)
    return body
}

// ── Output Formatting ───────────────────────────────────────────────────────

/** Formats a doc entry as a single line with name and tags. */
function formatDocEntry(doc: DocFile, raw: boolean, nameColor: typeof chalk.cyan): string {
    if (raw) {
        const tags = doc.tags.length > 0 ? ` [${doc.tags.join(', ')}]` : ''
        return `${doc.name}${tags}`
    }
    const tags = doc.tags.length > 0 ? chalk.gray(`  (${doc.tags.join(', ')})`) : ''
    return `  ${nameColor(doc.name)}${tags}`
}

/**
 * Prints a topic list with optional strong/weak grouping.
 * When weak is empty, prints a flat list. When both are provided,
 * prints strong matches first with weak matches in a separate section.
 */
function printTopicList(strong: DocFile[], weak: DocFile[], raw: boolean, filtered = false, peek = false): void {
    if (strong.length === 0 && weak.length === 0) {
        console.log(raw ? '# No matches found.' : chalk.gray('\nNo matches found.\n'))
        return
    }

    const sorted = (docs: DocFile[]) => [...docs].sort((a, b) => a.name.localeCompare(b.name))

    const printDocs = (docs: DocFile[], nameColor: typeof chalk.cyan) => {
        for (const doc of sorted(docs)) {
            if (peek) {
                console.log(raw ? `${doc.name}: ${doc.summary}` : `  ${nameColor(doc.name)}: ${doc.summary}`)
            } else {
                console.log(formatDocEntry(doc, raw, nameColor))
            }
        }
    }

    if (strong.length > 0) {
        const header = filtered ? 'Matching topics:' : 'Available topics:'
        console.log(raw ? `# ${header}` : chalk.bold(`\n${header}\n`))
        printDocs(strong, chalk.cyan)
    }

    if (weak.length > 0) {
        if (strong.length === 0) {
            console.log(raw ? '# No matches found.' : chalk.gray('\nNo matches found.'))
        } else if (raw) {
            console.log('')
        }
        console.log(raw ? '# Possibly related topics:' : chalk.bold('\nPossibly related topics:\n'))
        printDocs(weak, chalk.white)
    }
}

/** Prints name: summary lines for a list of docs. */
function printSummaries(docs: DocFile[], raw: boolean): void {
    for (const doc of docs) {
        if (raw) {
            console.log(`${doc.name}: ${doc.summary}`)
        } else {
            console.log(`  ${chalk.cyan(doc.name)}: ${doc.summary}`)
        }
    }
}

/** Prints a context message, formatted for raw (# comment) or pretty (bold). */
function printMessage(text: string, raw: boolean): void {
    console.log(raw ? `# ${text}` : chalk.bold(`\n${text}\n`))
}

function printDisambiguationHint(raw: boolean): void {
    const hint = 'Use `now-sdk explain <name>` with a topic name to expand.'
    console.log(raw ? `# ${hint}` : chalk.gray(`\n${hint}`))
}

/** Renders markdown with chalk formatting for terminal display. */
function printFormattedMarkdown(name: string, content: string, tags: string[]): void {
    console.log(`\n${chalk.cyan('═'.repeat(80))}`)
    console.log(chalk.bold.cyan(`  ${name}`))
    if (tags.length > 0) {
        console.log(chalk.gray(`  Tags: ${tags.join(', ')}`))
    }
    console.log(`${chalk.cyan('═'.repeat(80))}\n`)

    const lines = content.split('\n')
    let inCodeBlock = false

    for (let line of lines) {
        if (line.startsWith('```')) {
            inCodeBlock = !inCodeBlock
            console.log(chalk.dim(line))
            continue
        }

        if (inCodeBlock) {
            console.log(chalk.green(line))
            continue
        }

        if (line.startsWith('# ')) {
            console.log(chalk.bold.cyan(line.replace(/^# /, '')))
            continue
        } else if (line.startsWith('## ')) {
            console.log(`\n${chalk.bold.yellow(line.replace(/^## /, ''))}`)
            continue
        } else if (line.startsWith('### ')) {
            console.log(chalk.bold.white(line.replace(/^### /, '')))
            continue
        }

        line = line
            .replace(/\[([^\]]+)\]\([^)]+\)/g, chalk.cyan('$1'))
            .replace(/`([^`]+)`/g, chalk.green('$1'))
            .replace(/\*\*([^*]+)\*\*/g, chalk.bold('$1'))
            .replace(/\*([^*]+)\*/g, chalk.italic('$1'))
            .replace(/^(\s*)([*-])\s/, `$1${chalk.cyan('•')} `)

        console.log(line)
    }
}
